get_seo_configuration.code:
import (
	"fmt"
)

resp, err := client.SeoConfigurationSettings().GetSeoConfiguration(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
configuration := resp.Map().(map[string]any)["seo_configuration"].(map[string]any)
store := configuration["global_store_settings"].(map[string]any)
fmt.Println(store["store_name"], store["title_separator"])
for _, row := range configuration["document_root"].(map[string]any)["items"].([]any) {
	file := row.(map[string]any)
	fmt.Println(file["config_key"], file["file_name"])
}

